class apb_transaction extends uvm_sequence_item;
  
  // Request fields: generated by a sequence
  rand bit [7:0]  addr;
  rand bit        write; // 0 = read, 1 = write
  rand bit [31:0] wdata;
  rand bit [3:0]  strb;
  rand bit [2:0]  prot;

  // Response fields: populated from the DUT
  logic [31:0] rdata;
  logic        slverr;
  
  // Transfer metadata; not part of the APB interface.
  int unsigned wait_cycles; 
  bit          aborted;
  
  `uvm_object_utils_begin(apb_transaction)
    `uvm_field_int(addr,        UVM_DEFAULT | UVM_HEX)
    `uvm_field_int(write,       UVM_DEFAULT | UVM_BIN)
    `uvm_field_int(wdata,       UVM_DEFAULT | UVM_HEX)
    `uvm_field_int(strb,        UVM_DEFAULT | UVM_BIN)
    `uvm_field_int(prot,        UVM_DEFAULT | UVM_BIN)
    `uvm_field_int(rdata,       UVM_DEFAULT | UVM_HEX)
    `uvm_field_int(slverr,      UVM_DEFAULT | UVM_BIN)
    `uvm_field_int(wait_cycles, UVM_DEFAULT | UVM_DEC)
    `uvm_field_int(aborted,     UVM_DEFAULT | UVM_BIN) 
  `uvm_object_utils_end

  constraint strb_c {
    if (!write)
      strb == 4'b0000;
  }

  function new(string name = "apb_transaction");
    super.new(name);
  endfunction : new

endclass : apb_transaction